using CodexBackup.Core;
using Microsoft.Data.Sqlite;
using Xunit;

namespace CodexBackup.Tests;

public class CoreAdapterTests
{
    [Fact] public async Task PlausibleButIncompleteThreadsSchemaIsRejected()
    {
        using var t=new TestTree();t.Dir("stage");SQLitePCL.Batteries_V2.Init();
        using(var db=new SqliteConnection($"Data Source={Path.Combine(t.Root,"stage/state_5.sqlite")};Pooling=False")) {db.Open();using var cmd=db.CreateCommand();cmd.CommandText="CREATE TABLE threads(cwd TEXT,rollout_path TEXT)";cmd.ExecuteNonQuery();}
        await Assert.ThrowsAsync<BackupException>(()=>new CoreRestoreAdapter().PrepareAsync(Path.Combine(t.Root,"stage"),"C:/old/.codex",new Dictionary<string,string>()));
    }
    [Fact] public void CustomCoreHomeIsRecognizedByKindAndShape()
    {
        Assert.True(CoreRestoreAdapter.IsCandidate(new BackupRoot {Id="core",Kind=SourceKind.Core,IsDirectory=true,OriginalPath="D:/custom-home"},[new FileRecord {RootId="core",RelativePath="state_5.sqlite"}]));
    }
    [Fact] public async Task PassiveProjectsAndThreadAssociationsAreRemapped()
    {
        using var t=new TestTree();t.Write("stage/.codex-global-state.json","{\"local-projects\":[{\"id\":\"p\",\"name\":\"P\",\"rootPaths\":[\"C:/old/project\"],\"command\":\"disable\"}],\"project-order\":[\"p\"],\"thread-workspace-root\":{\"thread\":\"C:/old/project\"}}");
        await new CoreRestoreAdapter().PrepareAsync(Path.Combine(t.Root,"stage"),"C:/old/.codex",new Dictionary<string,string>{{"C:/old","E:/new"}});
        var node=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(Path.Combine(t.Root,"stage/.codex-global-state.json")))!;
        Assert.Equal("E:/new/project",node["local-projects"]![0]!["rootPaths"]![0]!.GetValue<string>());
        Assert.Equal("E:/new/project",node["thread-workspace-root"]!["thread"]!.GetValue<string>());
        Assert.Null(node["local-projects"]![0]!["command"]);
    }
    private static void Database(string path, string extra = "")
    {
        SQLitePCL.Batteries_V2.Init();
        using var db = new SqliteConnection($"Data Source={path};Pooling=False"); db.Open();
        using var cmd = db.CreateCommand();
        cmd.CommandText = ObservedSchema + ObservedMigrations + "INSERT INTO threads(id,cwd,rollout_path,daybreak_enabled,created_at,updated_at,source,model_provider,title,sandbox_policy,approval_mode) VALUES('a','C:\\old\\project','C:\\old\\.codex\\sessions\\a.jsonl',1,0,0,'cli','fixture','fixture','read-only','untrusted'); INSERT INTO thread_dynamic_tools(thread_id,position,name,description,input_schema) VALUES('a',0,'fixture','','{}'); INSERT INTO project_roots(project_id,position,path) VALUES('p',0,'D:\\unmapped');" + extra;
        cmd.CommandText=cmd.CommandText.Replace("INSERT INTO project_roots", "INSERT INTO projects(id,name,position,created_at_ms,updated_at_ms) VALUES('p','fixture',0,0,0); INSERT INTO project_roots",StringComparison.Ordinal);
        cmd.ExecuteNonQuery();
    }
    [Fact] public async Task KnownCoreRemapsOnlyStructuredPathsAndDisablesIntegrations()
    {
        using var t = new TestTree(); t.Dir("stage"); t.Dir("original");
        Database(Path.Combine(t.Root,"stage/state_5.sqlite"));
        File.Copy(Path.Combine(t.Root,"stage/state_5.sqlite"),Path.Combine(t.Root,"original/state_5.sqlite"));
        var original = File.ReadAllBytes(Path.Combine(t.Root,"original/state_5.sqlite"));
        foreach(var p in new[]{"config.toml","plugins/a","automations/a","sqlite/codex-dev.db","auth.json"}) t.Write("stage/"+p,"disabled");
        t.Write("stage/sessions/a.jsonl","C:\\old\\project");
        var notes = await new CoreRestoreAdapter().PrepareAsync(Path.Combine(t.Root,"stage"),"C:\\old\\.codex",new Dictionary<string,string>{{"C:\\old","E:\\new"}});
        using var db = new SqliteConnection($"Data Source={Path.Combine(t.Root,"stage/state_5.sqlite")};Pooling=False"); db.Open();
        using var cmd = db.CreateCommand(); cmd.CommandText="SELECT cwd FROM threads";
        Assert.Equal("E:\\new\\project",cmd.ExecuteScalar());
        cmd.CommandText="SELECT daybreak_enabled FROM threads"; Assert.Equal(0L,cmd.ExecuteScalar());
        cmd.CommandText="SELECT COUNT(*) FROM thread_dynamic_tools"; Assert.Equal(0L,cmd.ExecuteScalar());
        Assert.Equal("C:\\old\\project",File.ReadAllText(Path.Combine(t.Root,"stage/sessions/a.jsonl")));
        Assert.Equal(original,File.ReadAllBytes(Path.Combine(t.Root,"original/state_5.sqlite")));
        foreach(var p in new[]{"config.toml","plugins/a","automations/a","sqlite/codex-dev.db","auth.json"}) Assert.True(File.Exists(Path.Combine(t.Root,"stage/.codex-backup-disabled",p)));
        Assert.Contains(notes,n=>n.Contains("D:\\unmapped"));
    }
    [Theory]
    [InlineData("CREATE TABLE surprise_jobs(x TEXT);")]
    [InlineData("CREATE TRIGGER sqliteX_evil AFTER UPDATE ON threads BEGIN DELETE FROM threads; END;")]
    [InlineData("ALTER TABLE threads ADD COLUMN future_command TEXT;")]
    [InlineData("PRAGMA user_version=99;")]
    [InlineData("UPDATE _sqlx_migrations SET checksum=X'00' WHERE version=54;")]
    [InlineData("CREATE TRIGGER surprise AFTER UPDATE ON threads BEGIN DELETE FROM threads; END;")]
    public async Task UnknownSchemaIsRejected(string schema)
    {
        using var t=new TestTree(); t.Dir("stage"); Database(Path.Combine(t.Root,"stage/state_5.sqlite"),schema);
        await Assert.ThrowsAsync<BackupException>(()=>new CoreRestoreAdapter().PrepareAsync(Path.Combine(t.Root,"stage"),"C:\\old\\.codex",new Dictionary<string,string>()));
    }
    [Fact] public async Task MappingUsesLongestBoundaryPrefixAndSanitizesGlobalState()
    {
        using var t=new TestTree();t.Dir("stage");
        t.Write("stage/.codex-global-state.json","{\"electron-saved-workspace-roots\":[\"C:/old/project\",\"C:/older/project\"],\"electron-workspace-root-labels\":{\"C:/old/project\":\"Label\"},\"run-command\":\"do not activate\"}");
        t.Write("stage/memories/obsidian-vault-path.txt","C:/old/vault");
        await new CoreRestoreAdapter().PrepareAsync(Path.Combine(t.Root,"stage"),"C:/old/.codex",new Dictionary<string,string>{{"C:/old","E:/new"},{"C:/old/project","F:/project"}});
        var result=File.ReadAllText(Path.Combine(t.Root,"stage/.codex-global-state.json"));
        Assert.Contains("F:/project",result);Assert.Contains("C:/older/project",result);Assert.DoesNotContain("run-command",result);
        Assert.Equal("E:/new/vault",File.ReadAllText(Path.Combine(t.Root,"stage/memories/obsidian-vault-path.txt")).Trim());
    }
    [Fact] public async Task ReservedQuarantineCollisionRejectsBeforeChangingFiles()
    {
        using var t=new TestTree();t.Write("stage/.codex-backup-disabled/a","original");t.Write("stage/config.toml","config");
        await Assert.ThrowsAsync<BackupException>(()=>new CoreRestoreAdapter().PrepareAsync(Path.Combine(t.Root,"stage"),"C:/old/.codex",new Dictionary<string,string>()));
        Assert.True(File.Exists(Path.Combine(t.Root,"stage/config.toml")));
    }
    [Fact] public async Task RelativeMappingTargetsAreRejected()
    {
        using var t=new TestTree();t.Dir("stage");
        await Assert.ThrowsAsync<BackupException>(()=>new CoreRestoreAdapter().PrepareAsync(Path.Combine(t.Root,"stage"),"C:/old/.codex",new Dictionary<string,string>{{"C:/old","relative/new"}}));
    }
    // Observed schema and migration metadata only, read immutable/read-only on 2026-09-11. No user records.
    private const string ObservedSchema = "CREATE TABLE _sqlx_migrations (\n    version BIGINT PRIMARY KEY,\n    description TEXT NOT NULL,\n    installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    success BOOLEAN NOT NULL,\n    checksum BLOB NOT NULL,\n    execution_time BIGINT NOT NULL\n);\nCREATE TABLE backfill_state (\r\n    id INTEGER PRIMARY KEY CHECK (id = 1),\r\n    status TEXT NOT NULL,\r\n    last_watermark TEXT,\r\n    last_success_at INTEGER,\r\n    updated_at INTEGER NOT NULL\r\n);\nCREATE TABLE external_agent_config_imports (\r\n    import_id TEXT PRIMARY KEY,\r\n    completed_at_ms INTEGER NOT NULL,\r\n    successes TEXT NOT NULL,\r\n    failures TEXT NOT NULL\r\n, provider_id TEXT);\nCREATE TABLE project_idempotency_keys (\r\n    key TEXT PRIMARY KEY,\r\n    project_id TEXT NOT NULL,\r\n    created_at_ms INTEGER NOT NULL\r\n);\nCREATE TABLE project_roots (\r\n    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,\r\n    position INTEGER NOT NULL,\r\n    path TEXT NOT NULL,\r\n    PRIMARY KEY (project_id, position)\r\n);\nCREATE TABLE projects (\r\n    id TEXT PRIMARY KEY,\r\n    name TEXT NOT NULL,\r\n    metadata TEXT NOT NULL DEFAULT '{}',\r\n    position INTEGER NOT NULL,\r\n    created_at_ms INTEGER NOT NULL,\r\n    updated_at_ms INTEGER NOT NULL\r\n);\nCREATE TABLE remote_control_enrollments (\r\n    websocket_url TEXT NOT NULL,\r\n    account_id TEXT NOT NULL,\r\n    app_server_client_name TEXT NOT NULL,\r\n    server_id TEXT NOT NULL,\r\n    environment_id TEXT NOT NULL,\r\n    server_name TEXT NOT NULL,\r\n    updated_at INTEGER NOT NULL, remote_control_enabled INTEGER,\r\n    PRIMARY KEY (websocket_url, account_id, app_server_client_name)\r\n);\nCREATE TABLE rollout_migration_skipped_rollouts (\r\n    migration_id TEXT NOT NULL,\r\n    rollout_path TEXT NOT NULL,\r\n    rollout_size_bytes INTEGER NOT NULL,\r\n    rollout_modified_at_ns INTEGER NOT NULL,\r\n    skip_reason TEXT NOT NULL,\r\n    skipped_at INTEGER NOT NULL,\r\n    PRIMARY KEY (migration_id, rollout_path)\r\n);\nCREATE TABLE rollout_migration_state (\r\n    migration_id TEXT PRIMARY KEY,\r\n    last_checked_thread_created_at INTEGER,\r\n    last_checked_thread_id TEXT,\r\n    updated_at INTEGER NOT NULL\r\n);\nCREATE TABLE thread_artifacts (\r\n    id TEXT PRIMARY KEY,\r\n    thread_id TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE,\r\n    artifact_type TEXT NOT NULL,\r\n    identity_key TEXT NOT NULL,\r\n    payload TEXT NOT NULL,\r\n    created_at INTEGER NOT NULL,\r\n    UNIQUE (thread_id, artifact_type, identity_key)\r\n);\nCREATE TABLE thread_dynamic_tools (\r\n    thread_id TEXT NOT NULL,\r\n    position INTEGER NOT NULL,\r\n    name TEXT NOT NULL,\r\n    description TEXT NOT NULL,\r\n    input_schema TEXT NOT NULL, defer_loading INTEGER NOT NULL DEFAULT 0, namespace TEXT,\r\n    PRIMARY KEY(thread_id, position),\r\n    FOREIGN KEY(thread_id) REFERENCES threads(id) ON DELETE CASCADE\r\n);\nCREATE TABLE thread_sections (\r\n    id TEXT PRIMARY KEY,\r\n    name TEXT NOT NULL\r\n, appearance TEXT);\nCREATE TABLE thread_spawn_edges (\r\n    parent_thread_id TEXT NOT NULL,\r\n    child_thread_id TEXT NOT NULL PRIMARY KEY,\r\n    status TEXT NOT NULL\r\n);\nCREATE TABLE threads (\r\n    id TEXT PRIMARY KEY,\r\n    rollout_path TEXT NOT NULL,\r\n    created_at INTEGER NOT NULL,\r\n    updated_at INTEGER NOT NULL,\r\n    source TEXT NOT NULL,\r\n    model_provider TEXT NOT NULL,\r\n    cwd TEXT NOT NULL,\r\n    title TEXT NOT NULL,\r\n    sandbox_policy TEXT NOT NULL,\r\n    approval_mode TEXT NOT NULL,\r\n    tokens_used INTEGER NOT NULL DEFAULT 0,\r\n    has_user_event INTEGER NOT NULL DEFAULT 0,\r\n    archived INTEGER NOT NULL DEFAULT 0,\r\n    archived_at INTEGER,\r\n    git_sha TEXT,\r\n    git_branch TEXT,\r\n    git_origin_url TEXT\r\n, cli_version TEXT NOT NULL DEFAULT '', first_user_message TEXT NOT NULL DEFAULT '', agent_nickname TEXT, agent_role TEXT, memory_mode TEXT NOT NULL DEFAULT 'enabled', model TEXT, reasoning_effort TEXT, agent_path TEXT, created_at_ms INTEGER, updated_at_ms INTEGER, thread_source TEXT, preview TEXT NOT NULL DEFAULT '', recency_at INTEGER NOT NULL DEFAULT 0, recency_at_ms INTEGER NOT NULL DEFAULT 0, history_mode TEXT NOT NULL DEFAULT 'legacy', name TEXT, is_pinned INTEGER NOT NULL DEFAULT 0, thread_section_id TEXT\r\n    REFERENCES thread_sections(id) ON DELETE SET NULL, section_position INTEGER, section_entered_at_ms INTEGER, project_id TEXT\r\n    REFERENCES projects(id) ON DELETE SET NULL, originator TEXT, daybreak_enabled BOOLEAN);\nCREATE INDEX idx_projects_position\r\n    ON projects(position ASC, id ASC);\nCREATE INDEX idx_thread_artifacts_thread_created_id\r\n    ON thread_artifacts(thread_id, created_at, id);\nCREATE INDEX idx_thread_dynamic_tools_thread ON thread_dynamic_tools(thread_id);\nCREATE INDEX idx_thread_spawn_edges_parent_status\r\n    ON thread_spawn_edges(parent_thread_id, status);\nCREATE INDEX idx_threads_archived ON threads(archived);\nCREATE INDEX idx_threads_archived_cwd_created_at_ms ON threads(archived, cwd, created_at_ms DESC, id DESC);\nCREATE INDEX idx_threads_archived_cwd_recency_at_ms\r\n    ON threads(archived, cwd, recency_at_ms DESC, id DESC);\nCREATE INDEX idx_threads_archived_cwd_updated_at_ms ON threads(archived, cwd, updated_at_ms DESC, id DESC);\nCREATE INDEX idx_threads_created_at ON threads(created_at DESC, id DESC);\nCREATE INDEX idx_threads_created_at_ms ON threads(created_at_ms DESC, id DESC);\nCREATE INDEX idx_threads_pinned_recency_at_ms\r\n    ON threads(archived, recency_at_ms DESC, id DESC)\r\n    WHERE is_pinned = 1 AND preview <> '';\nCREATE INDEX idx_threads_project_id\r\n    ON threads(project_id, archived, created_at_ms DESC, id DESC)\r\n    WHERE project_id IS NOT NULL;\nCREATE INDEX idx_threads_project_recency\r\n    ON threads(project_id, recency_at_ms DESC)\r\n    WHERE archived = 0 AND project_id IS NOT NULL;\nCREATE INDEX idx_threads_provider ON threads(model_provider);\nCREATE INDEX idx_threads_recency_at_ms\r\n    ON threads(recency_at_ms DESC, id DESC);\nCREATE INDEX idx_threads_section_position\r\n    ON threads(archived, thread_section_id, section_position ASC, id ASC)\r\n    WHERE thread_section_id IS NOT NULL;\nCREATE INDEX idx_threads_section_recency_at_ms\r\n    ON threads(archived, thread_section_id, recency_at_ms DESC, id DESC)\r\n    WHERE thread_section_id IS NOT NULL;\nCREATE INDEX idx_threads_source ON threads(source);\nCREATE INDEX idx_threads_updated_at ON threads(updated_at DESC, id DESC);\nCREATE INDEX idx_threads_updated_at_ms ON threads(updated_at_ms DESC, id DESC);\nCREATE INDEX idx_threads_visible_created_at_ms\r\n    ON threads(archived, created_at_ms DESC)\r\n    WHERE preview <> '';\nCREATE INDEX idx_threads_visible_recency_at_ms\r\n    ON threads(archived, recency_at_ms DESC, id DESC)\r\n    WHERE preview <> '';\nCREATE INDEX idx_threads_visible_updated_at_ms\r\n    ON threads(archived, updated_at_ms DESC)\r\n    WHERE preview <> '';\nCREATE TRIGGER threads_created_at_ms_after_insert\r\nAFTER INSERT ON threads\r\nWHEN NEW.created_at_ms IS NULL\r\nBEGIN\r\n    UPDATE threads\r\n    SET created_at_ms = NEW.created_at * 1000\r\n    WHERE id = NEW.id;\r\nEND;\nCREATE TRIGGER threads_created_at_ms_after_update\r\nAFTER UPDATE OF created_at ON threads\r\nWHEN NEW.created_at != OLD.created_at\r\n AND NEW.created_at_ms IS OLD.created_at_ms\r\nBEGIN\r\n    UPDATE threads\r\n    SET created_at_ms = NEW.created_at * 1000\r\n    WHERE id = NEW.id;\r\nEND;\nCREATE TRIGGER threads_recency_at_after_insert\r\nAFTER INSERT ON threads\r\nWHEN NEW.recency_at_ms = 0\r\nBEGIN\r\n    UPDATE threads\r\n    SET recency_at = NEW.updated_at,\r\n        recency_at_ms = COALESCE(NEW.updated_at_ms, NEW.updated_at * 1000)\r\n    WHERE id = NEW.id;\r\nEND;\nCREATE TRIGGER threads_updated_at_ms_after_insert\r\nAFTER INSERT ON threads\r\nWHEN NEW.updated_at_ms IS NULL\r\nBEGIN\r\n    UPDATE threads\r\n    SET updated_at_ms = NEW.updated_at * 1000\r\n    WHERE id = NEW.id;\r\nEND;\nCREATE TRIGGER threads_updated_at_ms_after_update\r\nAFTER UPDATE OF updated_at ON threads\r\nWHEN NEW.updated_at != OLD.updated_at\r\n AND NEW.updated_at_ms IS OLD.updated_at_ms\r\nBEGIN\r\n    UPDATE threads\r\n    SET updated_at_ms = NEW.updated_at * 1000\r\n    WHERE id = NEW.id;\r\nEND;";
